-- Hound: Golf's four courses, nine holes each (par 36), as data. See
-- 0200_golf.sql for the game; this only fills golf_courses and
-- golf_holes, and can be run again to replace them.
--
-- Yards: d from the tee, lat across (right is +). Every hole has its own
-- dogleg (center), fairway (half-width fairway_w), green and pin, and
-- hazards placed where a normal drive or approach can find them, but not
-- on every line. Water always has a drop on the fairway (past a carry
-- from the tee, on the far side). Every green breaks: green.break is how
-- far a putt drifts across the hole per yard it rolls (+ to the right),
-- so a long putt aimed straight at the pin misses and reading it (aim)
-- matters. A hole plays the same for everyone; only its wind moves
-- (±3 mph a day).
--
--   links     Seaside Links: wind off the sea (6–14 mph), pot bunkers,
--             the sea itself on 2, 4 and 6, a burn across 8
--   desert    Canyon Desert: carries over sand and waste, one pond (4),
--             canyon walls close in (out of bounds nearer)
--   park      Lakeside Park: tree-lined, a lake or a pond on six holes
--   mountain  Ridge Mountain: tree-lined, downhill and uphill holes, a
--             glacier lake, a stream and the Lodge's pond
--
-- Run this once, after 0200, in the SQL Editor.

insert into public.golf_courses (id, name, style, note, sort) values ('links', 'Seaside Links', 'links', 'Wind off the sea, pot bunkers', 1)
  on conflict (id) do update set name = excluded.name, style = excluded.style, note = excluded.note, sort = excluded.sort;
insert into public.golf_courses (id, name, style, note, sort) values ('desert', 'Canyon Desert', 'desert', 'Carries over sand', 2)
  on conflict (id) do update set name = excluded.name, style = excluded.style, note = excluded.note, sort = excluded.sort;
insert into public.golf_courses (id, name, style, note, sort) values ('park', 'Lakeside Park', 'park', 'Trees and water', 3)
  on conflict (id) do update set name = excluded.name, style = excluded.style, note = excluded.note, sort = excluded.sort;
insert into public.golf_courses (id, name, style, note, sort) values ('mountain', 'Ridge Mountain', 'mountain', 'Big drops, thin air', 4)
  on conflict (id) do update set name = excluded.name, style = excluded.style, note = excluded.note, sort = excluded.sort;

